// 1. Validate status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Validate JSON response
pm.test("Response is valid JSON", function () {
    pm.response.to.be.json;
});

// Parse response
const response = pm.response.json();

// 3. Validate returned ID
pm.test("Returned ID matches saved user ID", function () {
    const userId = Number(
        pm.collectionVariables.get("userId")
    );

    pm.expect(response.id).to.eql(userId);
});

// 4. Validate updated name
pm.test("Updated name is correct", function () {
    pm.expect(response.name).to.eql(
        pm.variables.get("updatedName")
    );
});

// 5. Validate updated email
pm.test("Updated email is correct", function () {
    pm.expect(response.email).to.eql(
        pm.variables.get("updatedEmail")
    );
});

// 6. Validate updated company name
pm.test("Updated company name is correct", function () {
    pm.expect(response.company.name).to.eql(
        pm.variables.get("updatedCompanyName")
    );
});

// 7. Validate phone is not empty
pm.test("Phone number is not empty", function () {
    pm.expect(response.phone).to.be.a("string");
    pm.expect(response.phone.trim()).to.not.equal("");
});

